commands:
cd /home/runner/work/prflow/prflow
BRANCH=$(.prflow/vendor/prflow/scripts/branch-for-issue.py 1422 --title-file .prflow/tmp/devflow-issue-1422-title.txt) || { echo "FAIL branch-for-issue.py"; exit 1; }
echo "BRANCH=$BRANCH"
[ -n "$BRANCH" ] || { echo "FAIL empty branch name"; exit 1; }
git checkout -b "$BRANCH" "origin/main"
